CREATE TABLE "Flight" ("id" TEXT NOT NULL, "number" TEXT NOT NULL, "departureAirportId" TEXT NOT NULL, "departureTerminal" TEXT, "departureGate" TEXT, "departureScheduleGateOriginal" INTEGER, "departureScheduleGateEstimated" INTEGER, "departureScheduleGateActual" INTEGER, "departureScheduleRunwayOriginal" INTEGER, "departureScheduleRunwayEstimated" INTEGER, "departureScheduleRunwayActual" INTEGER, "scheduledArrivalAirportId" TEXT NOT NULL, "actualArrivalAirportId" TEXT NOT NULL, "arrivalTerminal" TEXT, "arrivalGate" TEXT, "arrivalBaggageBelt" TEXT, "arrivalScheduleGateOriginal" INTEGER, "arrivalScheduleGateEstimated" INTEGER, "arrivalScheduleGateActual" INTEGER, "arrivalScheduleRunwayOriginal" INTEGER, "arrivalScheduleRunwayEstimated" INTEGER, "arrivalScheduleRunwayActual" INTEGER, "arrivalWeatherTemperature" INTEGER, "delayForecastObservations" INTEGER, "delayForecastDelayMean" INTEGER, "delayForecastEarlyCount" INTEGER, "delayForecastOntimeCount" INTEGER, "delayForecastLate15Count" INTEGER, "delayForecastLate30Count" INTEGER, "delayForecastLate45Count" INTEGER, "delayForecastCanceledCount" INTEGER, "delayForecastDivertedCount" INTEGER, "equipmentTailNumber" TEXT, "equipmentModelName" TEXT, "equipmentRange" INTEGER, "equipmentCruisingSpeed" INTEGER, "equipmentIata" TEXT, "equipmentIcao" TEXT, "equipmentFirstFlightDate" INTEGER, "airlineId" TEXT NOT NULL, "changes" BLOB, "inboundFlights" BLOB, "codeshares" BLOB, "isCancelled" BOOLEAN NOT NULL, "hasOfficialData" TEXT NOT NULL, "distance" INTEGER NOT NULL, "lastKnownDepartureDate" INTEGER NOT NULL, "lastKnownArrivalDate" INTEGER NOT NULL, "created" INTEGER NOT NULL, "lastUpdated" INTEGER NOT NULL, "deleted" INTEGER, "departureGateIsPredicted" BOOLEAN NOT NULL DEFAULT 0, "departureRunwayIsPredicted" BOOLEAN NOT NULL DEFAULT 0, "arrivalGateIsPredicted" BOOLEAN NOT NULL DEFAULT 0, "arrivalRunwayIsPredicted" BOOLEAN NOT NULL DEFAULT 0, "equipmentPlaneName" TEXT, "equipmentRegistrationCountryCode" TEXT, "equipmentManufacturer" TEXT, "faaTmiType" TEXT, "faaTmiReason" TEXT, "faaTmiStartTime" INTEGER, "faaTmiEndTime" INTEGER, "ecRegulationStartTime" INTEGER, "ecRegulationEndTime" INTEGER, "ecRegulationReason" TEXT, "ecRegulationImpacts" TEXT, "departureFaaTerminalConstraintReasons" TEXT, "departureFaaTerminalConstraintExpirationDate" INTEGER, "arrivalFaaTerminalConstraintReasons" TEXT, "arrivalFaaTerminalConstraintExpirationDate" INTEGER, "departureFaaAirportDelayMinutes" INTEGER, "departureFaaAirportDelayExpirationDate" INTEGER, "departureFaaAirportDelayReason" TEXT, "arrivalFaaAirportDelayMinutes" INTEGER, "arrivalFaaAirportDelayExpirationDate" INTEGER, "arrivalFaaAirportDelayReason" TEXT, "departureAerodromeClosedStartTime" INTEGER, "departureAerodromeClosedEndTime" INTEGER, "departureAerodromeClosedReason" TEXT, "arrivalAerodromeClosedStartTime" INTEGER, "arrivalAerodromeClosedEndTime" INTEGER, "arrivalAerodromeClosedReason" TEXT, "faaPlannedInitiativeExpirationDate" INTEGER, "faaPlannedInitiativeTypes" TEXT, "faaPlannedInitiativeProbability" TEXT, "departureAtcSlot" INTEGER, "arrivalAtcSlot" INTEGER, "faaTmiProbabilityOfExtension" TEXT, "departureFaaAirportDelayTrend" TEXT, "arrivalFaaAirportDelayTrend" TEXT, "faaTmiFlightTargeted" BOOLEAN, "checkInScheduleOpen" INTEGER, "checkInScheduleClose" INTEGER, "departureScheduleGateInitial" INTEGER, "arrivalScheduleGateInitial" INTEGER, "departureFaaAirportDelayLastUpdated" INTEGER, "arrivalFaaAirportDelayLastUpdated" INTEGER, "turnaroundPredictionGateDeparture" INTEGER, "turnaroundPredictionGateArrival" INTEGER, "turnaroundPredictionRunwayDeparture" INTEGER, "turnaroundPredictionRunwayArrival" INTEGER, "turnaroundPredictionPublished" BOOLEAN, "equipmentModelId" TEXT, "equipmentStatsModelName" TEXT, "arrivalWeatherConditionName" TEXT, "arrivalWeatherIcon" TEXT, "arrivalWeatherWarnings" BLOB, "departureWeatherConditionName" TEXT, "departureWeatherIcon" TEXT, "departureWeatherTemperature" TEXT, "departureWeatherWarnings" BLOB, "arrivalWeatherLastUpdated" INTEGER, "arrivalWeatherSource" TEXT, "departureWeatherLastUpdated" INTEGER, "departureWeatherSource" TEXT, "departureNotams" BLOB, "arrivalNotams" BLOB, "departureBoardingStatus" TEXT, "departureBoardingLastUpdated" INTEGER, "accountId" INTEGER NOT NULL DEFAULT 0, "departurePredictedGate" TEXT, "departurePredictedGateRangeStart" TEXT, "departurePredictedGateRangeEnd" TEXT, "departurePredictedGateConcourse" TEXT, "arrivalPredictedGate" TEXT, "arrivalPredictedGateRangeStart" TEXT, "arrivalPredictedGateRangeEnd" TEXT, "arrivalPredictedGateConcourse" TEXT, "departureGatePredictionIsUnlocked" BOOLEAN, "arrivalGatePredictionIsUnlocked" BOOLEAN, PRIMARY KEY ("id"));
CREATE TABLE "Airport" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "iata" TEXT, "icao" TEXT, "city" TEXT NOT NULL, "country" TEXT NOT NULL, "countryCode" TEXT NOT NULL, "timeZoneIdentifier" TEXT NOT NULL, "latitude" DOUBLE NOT NULL, "longitude" DOUBLE NOT NULL, "relevance" INTEGER NOT NULL, "created" INTEGER NOT NULL, "lastUpdated" INTEGER NOT NULL, "deleted" INTEGER, "cityCode" TEXT, "website" TEXT, "accountId" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "Airline" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "iata" TEXT, "icao" TEXT, "alliance" TEXT, "website" TEXT, "facebookPage" TEXT, "twitterHandle" TEXT, "callsign" TEXT, "relevance" INTEGER NOT NULL, "created" INTEGER NOT NULL, "lastUpdated" INTEGER NOT NULL, "deleted" INTEGER, "formattedPhone" TEXT, "phoneURL" TEXT, "accountId" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "UserFlight" ("accountId" INTEGER NOT NULL, "userId" TEXT NOT NULL, "flightId" TEXT NOT NULL, "isRandom" BOOLEAN NOT NULL, "isProUpgrade" BOOLEAN NOT NULL, "isMyFlight" BOOLEAN NOT NULL, "isArchived" BOOLEAN NOT NULL, "importSource" TEXT, "sharingUrl" TEXT, "created" INTEGER NOT NULL, "lastUpdated" INTEGER NOT NULL, "deleted" INTEGER, PRIMARY KEY ("accountId", "userId", "flightId"));
CREATE TABLE "Ticket" ("accountId" INTEGER NOT NULL, "userId" TEXT NOT NULL, "flightId" TEXT NOT NULL, "pnr" TEXT, "seatNumber" TEXT, "seatPosition" TEXT, "cabinClass" TEXT, "flightReason" TEXT, "lastUpdated" INTEGER NOT NULL, "deleted" INTEGER, PRIMARY KEY ("accountId", "userId", "flightId"));
CREATE TABLE "FriendPushSetting" ("accountId" INTEGER NOT NULL, "userId" TEXT NOT NULL, "followedUserId" TEXT, "tier" TEXT NOT NULL, "newFlightAlert" BOOLEAN NOT NULL, "isDefault" BOOLEAN NOT NULL DEFAULT 0, "lastUpdated" INTEGER NOT NULL, UNIQUE ("accountId", "userId", "followedUserId"));
CREATE TABLE "Account" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "rawKind" TEXT NOT NULL, "rawStatus" TEXT NOT NULL, "delegatedUserId" TEXT, "authToken" TEXT NOT NULL, "created" INTEGER NOT NULL, "lastUpdated" INTEGER NOT NULL);
CREATE TABLE "Profile" ("accountId" INTEGER NOT NULL, "userId" TEXT NOT NULL, "fullName" TEXT NOT NULL, "firstName" TEXT, "lastUpdated" INTEGER NOT NULL, PRIMARY KEY ("accountId", "userId"));
CREATE TABLE "ConnectedFriendRelationship" ("accountId" INTEGER NOT NULL, "senderUserId" TEXT NOT NULL, "senderCloudIdentifier" TEXT NOT NULL, "senderAppleIdentifier" TEXT, "receiverUserId" TEXT NOT NULL, "receiverCloudIdentifier" TEXT NOT NULL, "receiverAppleIdentifier" TEXT, "senderHidingFlights" BOOLEAN NOT NULL DEFAULT 0, "delegatesAccess" BOOLEAN NOT NULL DEFAULT 0, "canBeDelegated" BOOLEAN NOT NULL DEFAULT 0, "senderFirstName" TEXT, "receiverFirstName" TEXT, "lastUpdated" INTEGER NOT NULL, "deleted" INTEGER, "otherUserProductID" TEXT, PRIMARY KEY ("accountId", "senderUserId", "receiverUserId"));
